quests[8120] = { title = "Die Schlacht um das Arathibecken!", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, $n. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dunkels in Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8121] = { title = "Erobert vier Stützpunkte", description = "$n, während die Schlachten über das Arathibecken wüten, haben sich die Neuigkeiten über Eure Taten wie ein Lauffeuer verbreitet. Wir schätzen Euch hier sehr und daher hoffe ich, dass Ihr die Mission erfüllen könnt, die ich Euch nun gebe.\n\nEs ist Zeit dem Bund von Arathor eine Nachricht zu senden. Wir müssen ihnen zeigen, dass ihre Stellungen im Arathibecken leicht angreifbar und schnell verloren sind. Das werden wir ihnen beweisen, indem wir gleichzeitig vier strategische Punkte im Arathibecken erobern und kontrollieren.\n\nSeid erfolgreich, $n und erntet mehr Respekt unter den Entweihten.", objectives = "Haltet vier Stützpunkte zur selben Zeit im Arathibecken und kehrt danach zu Todesmeister Dunkels nach Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8122] = { title = "Erobert fünf Stützpunkte", description = "Es ist schwer an Informationen zu gelangen, jetzt da wir so tief in diesem Konflikt stecken. Doch unsere Spione berichten, dass die Entschlossenheit des Bundes von Arathor schwindet. Wir sollten diesen Moment ausnutzen und eine große Offensive starten! Kehrt in das Arathibecken zurück und werft Euch unserem Feind entgegen. Verflucht und vernichtet sie, bis Ihr fünf strategische Punkte kontrolliert! Ihre Soldaten sollen blutend und schreiend in die Flucht geschlagen werden und ganz Azeroth mit zitternder Stimme von Eurer Grausamkeit berichten.\n\nGeht jetzt und erringt einen großen Sieg für die Entweihten.", objectives = "Haltet fünf Stützpunkte zur selben Zeit im Arathibecken und kehrt danach zu Todesmeister Dunkels nach Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8123] = { title = "Zerschlagt die Versorgungslinien Arathors", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, $n. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.", objectives = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8124] = { title = "Noch mehr Vorratskisten", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, $N. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpunkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.", objectives = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
