quests[8149] = { title = "Die Ehrung eines Helden", description = "Während des Erntedankfests in Azeroth danken wir unseren Helden für all die Opfer, die sie in unserem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Die Allianz kennt viele Helden, doch keine Heldensage und kein Lebensweg ist so tragisch, wie der von Uther Lightbringer.\n\nHelft uns Uther zu ehren, indem Ihr diese Opfergabe zu seinem Grabmal in den westlichen Pestländern bringt. Legt sie an seiner Statue nieder und kehrt zu mir zurück. Lasst Euch nicht zuviel Zeit, denn ich bin nur bis zum Ende des Erntedankfests hier.", objectives = "Reist zu Uthers Grabmal in den westlichen Pestländern und benutzt Uthers Tribut an seiner Statue. Kehrt zu Wagner Hammerstrike außerhalb von Ironforge zurück, bevor das Erntedankfest endet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8150] = { title = "Die Ehrung eines Helden", description = "Während des Erntedankfests in Azeroth danken wir unseren Helden für all die Opfer, die sie in unserem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Die Horde kennt viele Helden, doch niemand verkörpert Stärke und Opferbereitschaft so sehr, wie Grom Hellscream.\n\nHelft uns Grom zu ehren, indem Ihr diese Opfergabe zu seinem Monument im Demonfall-Canyon in Ashenvale bringt. Legt sie an seinem Monument nieder und kehrt zu mir zurück. Lasst Euch nicht zuviel Zeit, denn ich bin nur bis zum Ende des Erntedankfests hier.", objectives = "Reist zu Groms Monument im Demonfall-Canyon in Ashenvale und benutzt Groms Tribut am Fuße seines Monuments. Kehrt zu Javnir Nashak außerhalb von Orgrimmar zurück, bevor das Erntedankfest endet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8151] = { title = "Der Talisman des Jägers", description = "Ogtinc von Azshara sucht nach erfahrenen Jägern, genau wie Ihr es seid. Er ist ein Furbolg-Jäger, der seinen Stamm verlassen hat, um dem Zirkel des Cenarius zu helfen. Seine Lehren sollen das Wissen anderer, die sein Geschick teilen, bereichern und ihnen dabei helfen, das Gleichgewicht zu bewahren. Ihr würdet gut daran tun, mit ihm zu sprechen.\n\nOgtinc hält sich auf den Klippen von Azshara, nordöstlich der Ruinen von Eldarath, auf.", objectives = "Sprecht mit Ogtinc in Azshara.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8153] = { title = "Gehörnte Renner", description = "Die Renner tragen die gewaltigsten Geweihe die es in der bekannten Welt zu finden gibt. Solche Geweihe nutzt der Renner, um sich selbst zu verteidigen, indem er Feinde damit aufspießt. Meistens brechen sie dadurch die Spitzen der Geweihe ab. Perfekte, natürliche Geweihe sind das Zeichen für ein extrem selbstsicheres Tier.\n\nEin solches Geweih zu erlangen, würde auch in Euch dasselbe Selbstvertrauen fließen lassen.\n\nGeht auf die Jagd nach Mooshufrennern, findet die perfekten Geweihe und bringt sie mir.", objectives = "Bringt ein Paar perfekte Rennergeweihe zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8154] = { title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, $n. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", objectives = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8155] = { title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, $n. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", objectives = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8156] = { title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, $n. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", objectives = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Sergeant Maclear in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
