quests[8166] = { title = "Die Schlacht um das Arathibecken!", description = "$n, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8167] = { title = "Die Schlacht um das Arathibecken!", description = "$n, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8168] = { title = "Die Schlacht um das Arathibecken!", description = "$n, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Lichtmark in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8169] = { title = "Die Schlacht um das Arathibecken!", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, $n. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dunkels in Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8170] = { title = "Die Schlacht um das Arathibecken!", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, $n. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dunkels in Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8171] = { title = "Die Schlacht um das Arathibecken!", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, $n. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", objectives = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dunkels in Hammerfall zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8181] = { title = "Konfrontiert Yeh'kinya", description = "Meine eingehende Beschäftigung mit den Mosh'aru-Schrifttafeln bestätigt den Verdacht auf schlechte Neuigkeiten, $N. Hakkars wahre Gestalt, der Gott selbst, kann mit genau dem Ei wiedergeboren werden, in dem Ihr ihn gefangen habt. Yeh'kinya sagte Euch, dass es seiner Macht Einhalt gebiete, aber eigentlich dient es seiner Wiederherstellung! Der Troll hat Euch in die Irre geführt!\n\nGeht zu Yeh'kinya und verlangt das Ei von ihm. Betet, dass wir Hakkars Rückkehr noch rechtzeitig verhindern können!", objectives = "Sprecht mit Yeh'kinya.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8182] = { title = "Die Hand von Rastakhan", description = "$N, unsere schlimmsten Befürchtungen sind eingetroffen. Laut der Legende herrschte der Seelenschinder in der alten Welt der Trolle mit uneingeschränkter Macht und ließ das Böse und Terror walten. Wenn er jetzt nicht aufgehalten werden kann, dann könnte sich seine neue Schreckensherrschaft in ganz Azeroth verbreiten!\n\nEs gibt eine Gesandtschaft zandalarianischer Trolle, die uns beim Eindämmen dieser finsteren Flut behilflich sein könnte. Sie kampieren auf der Insel Yojamba, fern der Küste des Schlingendorntals, westlich der Ruinen von Zul'Kunda. Sprecht mit ihrem Anführer Molthor und betet dafür, dass er weiß wie man Hakkar bezwingen kann.", objectives = "Sprecht mit Molthor im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8183] = { title = "Das Herz von Hakkar", description = "Das Herz von Hakkar brennt noch immer im Inneren. Obwohl der Seelenschinder besiegt ist, bleibt das Wesen seiner Macht doch noch in dem verfluchten Organ enthalten.", objectives = "Bringt das Herz von Hakkar zu Molthor auf die Insel Yojamba.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
