quests[8201] = { title = "Die Schädelsammlung", description = "Es ist wahr. Hakkar hat sich in Zul'Gurub eingenistet und badet in den Kräften unserer Götter. Von ihm kontrollierte Priester haben damit begonnen, die Energien unserer heiligsten Gottheiten auf den Seelenschinder zu kanalisieren. Seine Macht wird schon bald die aller Wesen in Azeroth übersteigen. Er muss aufgehalten werden!\n\nHier, nehmt diese heilige Kordel. Findet die Priester, die es wagen die Energien unserer Götter zu kanalisieren, und reiht ihre Köpfe auf dieser Kordel aneinander.\n\nKehrt anschließend zu mir zurück.", objectives = "Reiht die Köpfe der 5 Kanalisierer auf der heiligen Kordel aneinander. Bringt dann die Trollschädelsammlung zu Exzhal auf der Insel Yojamba.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
