quests[8227] = { title = "Nats Maßband", description = "Inmitten von zerbrochenen Angelruten und anderen Geräten, liegt ein zusammengerolltes, seidenes Maßband. An dem Band hängt ein Schild mit der Aufschrift:\n\n\"Nat Pagle, die Düstermarschen.\"", objectives = "Bringt Nats Maßband zu Nat Pagle in den Düstermarschen zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
