quests[8231] = { title = "Wellenjagd", description = "Der Wellenhauer ist ein amphibisches Wildtier, das nur hier in Azshara vorkommt. Er ist gewandt und zäh.\n\nDie robusten, reflektierenden Schuppen eines Wellenhauers spiegeln die Stärke des Jägers wider.\n\nSpürt Wellenhauer entlang der Küste Azsharas auf, jagt sie und bringt mir ihre Schuppen.", objectives = "Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8232] = { title = "Der grüne Drache", description = "Ich entsende Euch nun auf eine gefährliche Jagd. Es gilt den grünen Drachen, Morphaz, zu bezwingen und mir seinen Zahn zu bringen. Morphaz haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nWenn Ihr ihn besiegen möchtet, solltet Ihr nicht alleine gehen. Dieser Drache ist der Feind von vielen - sucht nach anderen, die ihn ebenfalls zu vernichten suchen.\n\nDer Zahn des Drachen steht für die Macht, den ein Jäger in der Gesellschaft anderer findet. Bringt ihn zu mir und Ihr werdet viel gelernt haben.", objectives = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8233] = { title = "Ein simples Anliegen", description = "Lord Jorach Rabenholdt hat nach Euch rufen lassen. Die Angelegenheit ist geheim und ich kann auch nicht mehr dazu sagen.\n\nDas Rabenholdtanwesen liegt im Vorgebirge des Hügellands - haltet nach einem Pfad im Gebirge nordwestlich von Burg Durnholde Ausschau.", objectives = "Sprecht mit Lord Jorach Rabenholdt im Rabenholdtanwesen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8234] = { title = "Die versiegelte azurblaue Tasche", description = "Eins nach dem anderen. Ich habe eine kleine blaue Tasche verloren, deren Inhalt von privater Natur ist.\n\nWie dem auch sei, versucht erst gar nicht den Dieben nachzustellen, denn sie sind bereits tot. Wir wissen jedoch, dass diese Narren die Tasche nicht öffnen konnten. Sie verkauften sie also an einen Schamanen der Holzschlundfeste in Azshara als heiliges Relikt. Raffiniert.\n\nIch möchte, dass Ihr nach Azshara reist und die Tasche von dem Schamanen durch Geschick... oder mittels Kraft wiedererlangt. Ich glaube mit ersterer Methode dürftet Ihr mehr Glück haben. Habt Ihr sie, bringt sie zu Erzmagier Xylem in Azshara.", objectives = "Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8235] = { title = "Verschlüsselte Fragmente", description = "Lord Rabenholdt bittet uns beide um einen Gefallen. Er wünscht die Verzauberung von dieser Tasche zu entfernen.\n\nUnglücklicherweise hat man mir meine Abhandlungen über die Bannung von Zaubern vor Kurzem entwendet, nur um von Wilden zerstört zu werden. Die Überreste sind jedoch noch immer von Wert für mich.\n\nWenn Ihr mir genug verschlüsselte Fragmente bringen könnt, kann ich die Abhandlungen wiederherstellen. Am besten tötet Ihr dafür die Wildtiere Azsharas, da diese Kreaturen die Tendenz besitzen, alles aufzusammeln, was sie so finden können.", objectives = "Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8236] = { title = "Der azurblaue Schlüssel", description = "Es wird einige Zeit dauern, die Fragmente zu entschlüsseln und den Zauber zu bannen. Sobald ich mein Werk vollendet habe, werde ich die Tasche Lord Rabenholdt persönlich übergeben.\n\nAllerdings gibt es da noch das Problem mit dem Schlüssel, von dem gesagt wird, er befände sich im Besitz von Morphaz, einem grünen Drachen. Er haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nVersammelt Eure getreusten Freunde und begebt Euch zu seinem Hort. Lord Rabenholdt erwartet Euch mit dem Schlüssel.", objectives = "Bringt den azurblauen Schlüssel zu Lord Jorach Rabenholdt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8238] = { title = "Münzen der Gurubashi, Blutfratzen und Bleichborken", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8239] = { title = "Münzen der Sandwüter, Schädelspalter und Blutskalpe", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8240] = { title = "Ein Schmuckstück für Zanza", description = "Die Zerstörung der zahlreichen Schmuckstücke der Hakkari ist für uns von großer Bedeutung. Wir heißen sogar Außenseiter in unserem Stamm willkommen, um uns dabei in eigener Sache zu helfen!\n\nBringt, was auch immer für ein Schmuckstück ihr in Zul'Gurub finden solltet, zum Altar von Zanza und zerstört es. Ich werde Euch nur für dieses eine Mal eine zusätzliche Ehrenmünze unseres Stammes geben; dies liegt hoch über dem, was Ihr normalerweise erhalten würdet.\n\nWerdet selbst Zeuge des Segens von Zanza!", objectives = "Zerstört jedes Schmuckstück der Hakkari, das Ihr in Zul'Gurub findet, am Altar von Zanza auf der Insel Yojamba. Sprecht ganz in der Nähe mit Vinchaxa, sobald Ihr dies getan habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8241] = { title = "Nachschub an feurigem Fluxus: Eisen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
