quests[8249] = { title = "Plunderkisten benötigt", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8250] = { title = "Geschick der Magier", description = "Erzmagier Xylem hat seit kurzer Zeit begonnen sich umzuhören... nach jemanden mit Eurer Erfahrung.\n\nFalls Ihr ihn aufsuchen möchtet, dann könnt Ihr ihn in Azshara antreffen. Sein Turm steht hoch über den Klippen und der einzige Weg, der dort hinaufführt, ist ein Teleportationszauber, der von seinem arroganten Diener, Sanath Lim-yo, gewirkt wird.\n\nSanath kampiert unterhalb des Turms. Um ihn zu finden, müsst Ihr zu der Stelle reisen, an der sich Azsharas Hauptstraße beim Eingang zu den Ruinen von Eldarath gabelt. Geht von dort aus direkt nach Norden bis Ihr zu den Klippen kommt.", objectives = "Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8251] = { title = "Magischer Staub", description = "Die Blutelfen in Azshara haben eine Methode entwickelt, um magische Gegenstände, die sie erhalten, zu Staub zu pulverisieren. Dieser glitzernde Staub, der so produziert wird, gleicht nicht jenem, der sich durch eine übliche Entzauberung herstellen lässt.\n\nIch habe bereits meinen Lehrling entsendet, um durch Handel diesen Staub zu erlangen, doch er wurde ohne Umschweife grausam ermordet. Dafür müssen sie bezahlen.\n\nDie Zeiten der Konversation sind vorbei, $n. Sucht nach den Blutelfen entlang der Klippen von Azshara und wendet \"überzeugendere\" Mittel an, um an den glitzernden Staub zu kommen.", objectives = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8252] = { title = "Die Koralle der Sirenen", description = "Seht Euch nur um. Die Ruinen und Strände sind buchstäblich von den Grollflossen überrannt worden. Unlängst haben sie sich soweit mit dem Land vertraut gemacht, dass sie die seltensten und wertvollsten Elemente entdeckt haben, die in Azshara heimisch sind.\n\nGenau genommen spreche ich von der verzauberten Koralle - sie werden aus mir unerfindlichen Gründen davon angezogen. In der Bucht gibt es nur noch sehr wenige Exemplare, die für meine Forschungen jedoch unverzichtbar sind. Ich brauche Euch, um mir verzauberte Korallen von den Sirenen der Grollflossen zu beschaffen.", objectives = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8253] = { title = "Vernichtet Morphaz", description = "Es gibt einen grünen Drachen, tief im Versunkenen Tempel von Atal'Hakkar, der sich Morphaz nennt.\n\nVor Jahren überwältigte er mich aus einem kühnen Hinterhalt heraus und verschlang meinen Lehrling mit Haut und Haaren. Der Verlust eines Lehrlings ist mir zwar nicht unbekannt, allerdings trug dieser einen arkanen Splitter von unübertroffener Größe und Qualität.\n\nBitte versammelt Eure mächtigsten Verbündeten und dringt in die Tiefen des Tempels vor. Zerstört Morphaz und entreißt ihm den arkanen Splitter aus seinem Magen.", objectives = "Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8254] = { title = "Cenarische Hilfe", description = "Es ist der Weg des Göttlichen, mit dem denen geholfen wird, die in Not sind. Das wie ist unbedeutend - allein das warum zählt.\n\nDer Zirkel des Cenarius ist in derartigen Nöten. Sprecht mit Ogtinc, um ihnen in ihrer Notlage auszuhelfen. Er wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", objectives = "Sucht Ogtinc in Azshara auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8255] = { title = "Renner für einen höheren Zweck", description = "Die in Azshara lebenden Mooshufrenner sind prachtvolle Tiere, die ursprünglich aus dem Teufelswald stammen. Sie sind von Natur aus resistent gegen Krankheiten und Gifte und blieben so vor der Verderbnis in diesem Gebiet verschont. In ihrer ganzen Weisheit haben sie schlicht beschlossen, den Teufelswald zu verlassen.\n\nEs schmerzt mich von ganzem Herzen, dass ich Euch bitten muss, diese majestätischen Lebewesen für mich zu jagen. Sammelt vier Rennerdrüsen als erste Zutat für ein regenerierendes Mittel - ein Mittel, mit dem wir den Teufelswald heilen möchten.", objectives = "Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8256] = { title = "Sekret des Untodes", description = "Für dieses regenerierende Mittel braucht Ihr ein simples Rezept: ein Teil Gift, zwei Teile Heilmittel. Ihr habt bereits einen Teil des Heilmittels beschafft, nun müsst Ihr das Gift sammeln.\n\nMächtige Untote, wie die verweilenden Hochgeborenen, welche die Ruinen von Eldarath durchstreifen, sind dermaßen vom Bösen durchdrungen, dass es sich manchmal als eine Art dickflüssige, grünliche Flüssigkeit manifestiert. Unter den Lebenden ist diese Substanz als Sekret des Untodes bekannt.\n\nDie Wirksamkeit dieses widerwärtigen Elements ist derart mächtig, dass es genügen wird, wenn Ihr mir eine einfache Dosis des Sekrets bringt.", objectives = "Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8257] = { title = "Morphaz' Blut", description = "Jetzt zum letzten Teil, dem zweiten Heilmittel.\n\nDer grüne Drache Morphaz ist dafür bekannt, gegen alle Formen von Krankheit und Gift immun zu sein - viele Druiden erlitten den Tod, um uns diese Nachricht zu übermitteln. Es gibt keine Zweifel, dass sein Blut die für uns nötige Wirkung hat.\n\nEin Kurier des Zirkels des Cenarius wird die von Euch bereits beschafften Zutaten übernehmen, während Ihr nach der letzten sucht. Versammelt Eure Verbündeten und sucht den Unterschlupf des Drachen im Versunkenen Tempel von Atal'Hakkar auf. Bringt sein Blut anschließend zu Greta Mooshuf im Teufelswald.", objectives = "Tötet Morphaz im Versunkenen Tempel von Atal'Hakkar und bringt Greta Mooshuf im Teufelswald sein Blut. Der Eingang zum Versunkenen Tempel liegt in den Sümpfen des Elends.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8258] = { title = "Die Bedrohung durch Schattensichel", description = "Der Todesritter Schattensichel herrscht über das Große Ossuarium in Scholomance. Er droht die spirituelle Ebene zu seinen eigenen Zwecken zu missbrauchen... Er muss gestoppt werden! Dabei kommt das Orakel der Anrufung, bei dessen Herstellung Ihr behilflich wart, zum Einsatz.\n\nSetzt das Orakel inmitten des Kellergewölbes des Großen Ossuariums ein, um Schattensichels Geistergefolge herbeizurufen. Besiegt die Geister und der Todesritter selbst wird erscheinen. $n, bringt mir seinen Kopf! Lediglich seine Niederlage wird den Schaden, den er der spirituellen Ebene zugefügt hat, wieder umkehren können!", objectives = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des Großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn.\n\nBringt Schattensichels Kopf zu Sagorne Gratläufer im Tal der Weisheit in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
