quests[8409] = { title = "Verdorbenes Bier", description = "Die faulen Eier wurden wie geplant in den Braukessel geworfen. Zukünftige Ladungen Bier des Gasthauses von Süderstade sind somit erfolgreich verdorben worden!\n\nIhr solltet jetzt zurück zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal gehen und ihr von Eurem Erfolg berichten.", objectives = "Kehrt zur Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8410] = { title = "Elementarbeherrschung", description = "Bath'rah der Windbehüter sucht nach einem Schamanen von Eurer Weisheit. Als Zeichen Eurer Bereitschaft bittet er Euch, ihm Proben eines jeden Elements zu bringen.\n\nUm Bath'rah zu finden, begebt Euch zu dem Fluss östlich von Tarrens Mühle. Folgt seinem Verlauf Richtung Norden, irgendwann trefft Ihr auf die Ruinen, in denen sich Bath'rah niedergelassen hat.", objectives = "Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8411] = { title = "Die Beherrschung der Elemente", description = "Willkommen, $C. Bringt mir zuerst die Elemente und dann unterhalten wir uns.\n\nIch brauche erst das Feuer, die Luft, das Wasser und die Erde, bevor ich Euch vertraue, Mann. Ich muss wissen, ob Ihr gut unterrichtet seid.", objectives = "Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8412] = { title = "Geistertotem", description = "Die Elementare an diesem Ort haben sich gegen mich gewendet.\n\nIhr kennt Euch mit den Mächten der Totems besser als jeder andere aus und ich brauche jetzt ein Geistertotem zu meinem Schutz. Wir haben bereits die Elemente, jetzt brauchen wir etwas mit noch mehr Natur. Etwas noch Wilderes.\n\nIn den Westlichen Pestländern könnt Ihr Bären für Klauen und Spinnen für Augen töten. Mit etwas Glück, könnt Ihr beides auch bei den dort lebenden Aasgeiern finden, sie fressen alles.", objectives = "Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8413] = { title = "Die Macht des Voodoos", description = "Das Geistertotem alleine ist nicht stark genug. Um erfolgreich zu sein, benötigen wir noch etwas Voodoomagie.\n\nDie Trolle im Versunkenen Tempel besitzen Federn, die von mächtiger Voodoomagie erfüllt sind. Begebt Euch dorthin und besiegt Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Mit ihren Federn haben wir genug Macht, um ein starkes Geistertotem zu formen.", objectives = "Bringt Bath'rah dem Windbehüter die Voodoofedern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8414] = { title = "Austreibung des Bösen", description = "Seid gegrüßt, $C. Kreuzfahrer wie Ihr werden in solch abgeschiedenen Gegenden gerne gesehen.\n\nEure heilige Stärke wird gebraucht, um uns bei der Vernichtung der unzähligen Untoten hier zu helfen. Genau genommen bräuchten wir Euch, um eine große Anzahl von Geißelsteinen zu sammeln und sie anschließend zu Hohepriester Thel'danis zu bringen. Der Hohepriester bewacht Uthers Grabmal in Trauerhügel, nicht weit von hier.\n\nNur jemand mit einer Anstecknadel der Argentumdämmerung kann darauf hoffen Geißelsteine zu finden, sprecht also mit Offizier Reinherz, wenn Ihr noch keine besitzt.", objectives = "Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den Westlichen Pestländern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8415] = { title = "Zugwindlager", description = "Kommandant Ashlam Ehrenschlag sucht nach einem Paladin Eurer Reinheit und Euren Mutes, $n. Ihr könnt ihn im Zugwindlager im Süden der Westlichen Pestländer finden. Sucht nach ihm und helft ihm im Namen des Lichts!", objectives = "Sprecht mit Kommandanten Ashlam Ehrenschlag im Zugwindlager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8416] = { title = "Gereinigte Geißelsteine", description = "Das Böse wurde aus diesen Steinen getrieben, $n.\n\nIch weiß über Kommandant Ashlams Pläne Bescheid, er wird nur nach einem einzigen, gereinigten Geißelstein verlangen. Bringt ihn zu ihm, damit wir die Geißel ins Feuer der Gerechtigkeit tauchen können.", objectives = "Bringt den gereinigten Geißelstein zu Kommandant Ashlan Ehrenschlag an der Zugwindspitze.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8417] = { title = "Ein geplagter Geist", description = "In den Verwüsteten Landen gibt es einen geplagten Geist, der einst ein großer Held der Horde war. Die Ehre eines Kriegers stirbt nicht mit seinem Körper und es würde für Euch von Wert sein mit ihm zu sprechen.", objectives = "Sprecht mit dem gefallenen Helden der Horde am Eingang zu den Verwüsteten Landen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8418] = { title = "Erschaffung des Steins der Macht", description = "Jetzt müssen wir die gereinigten Geißelsteine kombinieren und eine Waffe herstellen, die die Reihen der Untoten erschüttert. Das ist keine einfache Aufgabe, $n. Nur die Trolle des Versunkenen Tempels besitzen diese Art seltener Magie, die fähig ist, das Böse von etwas gegen sich selbst zu richten.\n\nIm Tempel sind die Trolle bekannt als Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Verspürt keine Reue für ihre verderbten Seelen... sie sind nicht frei von Bösem.", objectives = "Beschafft Euch gelbe, blaue und grüne Voodoofedern von den Trollen im Versunkenen Tempel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8419] = { title = "Die Bitte eines Wichtels", description = "$n, ein Wichtel im Teufelswald namens Impsy hat nach Euch verlangt. Seine Bitte ist etwas merkwürdig, da er möchte, dass Ihr ihm ein Stück Teufelsstoff als Zeichen des guten Willens bringt. Bedenkt man die Macht, die Ihr bereits als Hexenmeister besitzt, kann ich nur vermuten, dass Ihr wisst, dass die Satyrn des Teufelswalds diesen Teufelsstoff bei sich tragen.\n\nIhr findet Impsy nördlich der Blutgiftfälle, von denen ich hörte, dass sie um diese Jahreszeit recht schön sein sollen.", objectives = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8420] = { title = "Heiß und brennend", description = "Vielleicht klingt es ja etwas komisch bei einem Wichtel, aber ich würde gerne meinen eigenen Begleiter haben. Das hätte ich wirklich gerne. Es ist nicht gerecht, dass Niby mich hat und ich niemanden!\n\nEs braucht ja gar nicht lebendig zu sein. Ich bräuchte etwas, um mit der Anfertigung beginnen zu können, zum Beispiel etwas Teufelsstoff. Die Satyrn hier im Teufelswald haben manchmal Teufelsstoff, Ihr müsstet also nur genug von ihnen töten, um welchen zu finden. Das hört sich doch gut an, oder?", objectives = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8421] = { title = "Das richtige Zeug", description = "Jetzt, da ich meinen Teufelsstoff habe, kann ich wirklich mit der Anfertigung *meines* Begleiters beginnen.\n\nIch werde etwas für die Augen brauchen. Vielleicht könnt Ihr mir etwas faules Holz vom Stamm der Eisenstämme besorgen, damit ich daraus ein Paar wunderschöne Augen schnitzen kann. Ihr findet sie im Norden, im Eisenwald.\n\nIch brauche auch etwas Blutgiftessenz, um meinem Begleiter diesen neuen dämonischen Duft zu verleihen. Die besudelten Schlamme haben diese Essenz und Ihr könnt sie gleich hier in der Nähe von Niby und mir finden.", objectives = "Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8422] = { title = "Federn von Trollen", description = "Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial.\n\nNur die Voodoofedern von den Trollen aus dem Versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Tötet sie. Tötet sie alle.\n\nDies ist keine gewöhnliche Aufgabe $n, also werde ich Eure Bemühungen belohnen, indem ich Euch etwas von Niby gebe - er wird es sowieso nicht mehr brauchen.", objectives = "Bringt 6 Voodoofedern von den Trollen aus dem Versunkenen Tempel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8423] = { title = "Kriegerverwandtschaft", description = "<Der Held betrachtet Euch.>\n\nIhr seid ein $C, ohne Zweifel. Ich würde Euch um eine ehrenhafte Aufgabe bitten, aber zuerst muss ich Eure Stärke testen.\n\nMan sagt, dass Rexxar die Schärfe seiner Klingen misst, indem er einen Hölleneber mit nur einem einzigen, schnellen Schlag erlegt. Jetzt werde ich Eure Stärke auf die gleiche Art messen.", objectives = "Tötet 7 Hölleneber in den Verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8424] = { title = "Krieg den Schattenanbetern", description = "Die weiterhin bestehende Gegenwart der Schattenanbeter in den Verwüsteten Landen ist schmerzhaft für mich. Ihre dunklen Rituale und Zauber bereiten mir heute mehr Qualen als es zu meinen Lebzeiten je etwas hätte tun können.\n\nIch kann ihnen mit Eurer Hilfe eine schmerzhafte Botschaft überbringen. Zieht hinfort und lasst meinen Zorn sprechen.", objectives = "Merzt die Schattenanbeter in den Verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8425] = { title = "Voodoofedern", description = "Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.\n\nMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.\n\nReist zu dem Versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neu bilden können, damit ich Euch belohnen kann.", objectives = "Bringt die Voodoofedern der Trolle im Versunkenen Tempel zu dem gefallenen Helden der Horde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8426] = { title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, $n! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", objectives = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8427] = { title = "Schlacht der Kriegshymnenschlucht", description = "Der Kampf gegen die Schildwachen der Silberschwingen in der Kriegshymnenschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, $n! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", objectives = "Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
